#include "stdlib/blas/base/dtrmv.h"
#include "stdlib/blas/base/dtrmv_cblas.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/min_view_buffer_index.h"
#include "stdlib/ndarray/base/min_view_buffer_index.h"

/**
* Performs one of the matrix-vector operations `x = A*x` or `x = A^T*x`, where `x` is an `N` element vector and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix.
*
* @param order     storage layout
* @param uplo      specifies whether `A` is an upper or lower triangular matrix
* @param trans     specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param diag      specifies whether `A` has a unit diagonal
* @param N         number of elements along each dimension of `A`
* @param A         input matrix
* @param LDA       stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param x         input vector
* @param strideX   `x` stride length
* @return         output value
*/
double API_SUFFIX(c_dtrmv)( const CBLAS_LAYOUT order, const CBLAS_UPLO uplo, const CBLAS_TRANSPOSE trans, const CBLAS_DIAG diag, const CBLAS_INT N, const double *A, const CBLAS_INT LDA, double *x, const CBLAS_INT strideX ) {
	CBLAS_INT sx = strideX;
	if ( sx < 0 ) {
		sx = -sx;
	}
	return API_SUFFIX(cblas_dtrmv)( order, uplo, trans, diag, N, A, LDA, x, sx );
}

/**
* Performs one of the matrix-vector operations `x = A*x` or `x = A^T*x` using alternative indexing semantics, where `x` is an `N` element vector and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix.
*
* @param uplo      specifies whether `A` is an upper or lower triangular matrix
* @param trans     specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param diag      specifies whether `A` has a unit diagonal
* @param N         number of elements along each dimension of `A`
* @param A         input matrix
* @param strideA1  stride of the first dimension of `A`
* @param strideA1  stride of the second dimension of `A`
* @param offsetA   starting index for `A`
* @param x         first input vector
* @param strideX   `x` stride length
* @param offsetX   starting index for `x`
* @return          output value
*/
double API_SUFFIX(c_dtrmv_ndarray)( const CBLAS_UPLO uplo, const CBLAS_TRANSPOSE trans, const CBLAS_DIAG diag, const CBLAS_INT N, const double *A, const CBLAS_INT strideA1, const CBLAS_INT strideA2, const CBLAS_INT offsetA, double *x, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	CBLAS_INT sx = strideX;
	if ( sx < 0 ) {
		sx = -sx;
	}
	x += stdlib_strided_min_view_buffer_index( N, strideX, offsetX ); // adjust array pointer
	const int64_t shape[] = { N, N };
	const int64_t strides[] = { strideA1, strideA2 };
	A += stdlib_ndarray_min_view_buffer_index( 2, shape, strides, offsetA ); // adjust array pointer
	return API_SUFFIX(cblas_dtrmv)( order, uplo, trans, diag, N, A, LDA, x, sx );
}
